CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
 CREATE SCHEMA auth;
 CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('request.test_uid',true),'')::uuid $$;
 CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql AS $$ SELECT coalesce(nullif(current_setting('request.test_role',true),''),'service_role') $$;
 CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql AS $$ SELECT coalesce(nullif(current_setting('request.test_jwt',true),''),'{}')::jsonb $$;
 CREATE TABLE users(user_id varchar(11) primary key,auth_id uuid);
 CREATE TABLE students(student_id varchar(11) primary key,student_name text);
 CREATE TABLE staffs(staff_id varchar(11) primary key,staff_name text);
 CREATE TABLE courses(course_id serial primary key,course_name text);
 CREATE TABLE course_sections(section_id serial primary key,course_id int,year int,semester int,section_number int);
 CREATE TABLE clearance_departments(dept_id serial primary key,dept_name text);
 CREATE TABLE clearance_templates(template_id serial primary key,course_id int,dept_id int,staff_id varchar(11),tier int default 1,is_active boolean default true);
 CREATE TABLE enrollments(student_id varchar(11),section_id int,CONSTRAINT enrollments_student_section_unique UNIQUE(student_id,section_id));
 CREATE TABLE clearance_records(clearance_id serial primary key,user_id varchar(11),template_id int,status varchar(20) default 'Pending',signed_at timestamptz,created_at timestamptz default now(),CONSTRAINT clearance_records_user_template_unique UNIQUE(user_id,template_id));
 CREATE TABLE clearance_tasks(assigned_task_id serial primary key,clearance_id int,status text);
