ALTER TABLE clearance_records ENABLE ROW LEVEL SECURITY;
ALTER TABLE clearance_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY fixture_clearances ON clearance_records TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY fixture_tasks ON clearance_tasks TO authenticated USING(true) WITH CHECK(true);
CREATE POLICY fixture_enrollments ON enrollments TO authenticated USING(true) WITH CHECK(true);
GRANT USAGE ON SCHEMA public,auth TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON clearance_records,clearance_tasks,enrollments TO authenticated;
GRANT SELECT ON clearance_templates,course_sections TO authenticated;
SELECT setval(pg_get_serial_sequence('clearance_templates','template_id'),2);
